insert into public.study_tests(id,title,subject,grade,level,path,questions) values
('liczby8-latwy-v1','Liczby i działania · łatwy','Matematyka','8','','testy/matematyka/liczby-dzialania.html?poziom=latwy','[{"no": 1, "question": "Jaką liczbę oznacza zapis XLVIII?", "topic": "Liczby rzymskie", "options": ["48", "38", "58", "46"], "correct": 0, "explanation": "XL oznacza 40, a VIII oznacza 8. Razem: 40 + 8 = 48."}, {"no": 2, "question": "Który zapis rzymski oznacza liczbę 94?", "topic": "Liczby rzymskie", "options": ["IC", "XCIV", "LXXXXVI", "XCVI"], "correct": 1, "explanation": "90 zapisujemy XC, a 4 jako IV. Dlatego 94 = XCIV."}, {"no": 3, "question": "Która liczba jest podzielna przez 3?", "topic": "Podzielność", "options": ["401", "502", "372", "251"], "correct": 2, "explanation": "Suma cyfr liczby 372 to 3 + 7 + 2 = 12. Liczba 12 dzieli się przez 3."}, {"no": 4, "question": "Która liczba jest podzielna jednocześnie przez 2 i przez 5?", "topic": "Podzielność", "options": ["125", "246", "333", "340"], "correct": 3, "explanation": "Liczba podzielna przez 2 i 5 jest podzielna przez 10, więc jej ostatnią cyfrą jest 0."}, {"no": 5, "question": "Która liczba jest pierwsza?", "topic": "Liczby pierwsze", "options": ["29", "1", "21", "27"], "correct": 0, "explanation": "29 ma dokładnie dwa dodatnie dzielniki: 1 i 29. Liczba 1 nie jest ani pierwsza, ani złożona."}, {"no": 6, "question": "Który rozkład liczby 60 na czynniki pierwsze jest poprawny?", "topic": "Rozkład na czynniki", "options": ["2 · 5²", "2² · 3 · 5", "2 · 3² · 5", "2² · 3²"], "correct": 1, "explanation": "60 = 2 · 2 · 3 · 5 = 2² · 3 · 5. Wszystkie czynniki 2, 3 i 5 są pierwsze."}, {"no": 7, "question": "Oblicz NWD(18, 24).", "topic": "NWD", "options": ["12", "72", "6", "3"], "correct": 2, "explanation": "Dzielniki wspólne to 1, 2, 3 i 6. Największy z nich to 6."}, {"no": 8, "question": "Oblicz NWW(4, 6).", "topic": "NWW", "options": ["2", "10", "24", "12"], "correct": 3, "explanation": "Wielokrotności 4: 4, 8, 12… Wielokrotności 6: 6, 12… Najmniejsza wspólna to 12."}, {"no": 9, "question": "Która liczba jest całkowita, ale nie jest naturalna?", "topic": "Rodzaje liczb", "options": ["−7", "3", "1/2", "√2"], "correct": 0, "explanation": "Liczby całkowite obejmują liczby ujemne, zero i dodatnie liczby całkowite. Ujemna liczba −7 nie jest naturalna."}, {"no": 10, "question": "Wskaż prawdziwą nierówność.", "topic": "Porównywanie liczb", "options": ["−5 > 0", "−3 > −5", "−3 < −5", "−3 = −5"], "correct": 1, "explanation": "Na osi liczbowej −3 leży na prawo od −5, więc jest większe."}, {"no": 11, "question": "Oblicz: 3/4 + 1/8.", "topic": "Działania na liczbach", "options": ["1/2", "5/8", "7/8", "4/12"], "correct": 2, "explanation": "3/4 = 6/8. Dodajemy: 6/8 + 1/8 = 7/8."}, {"no": 12, "question": "Oblicz: 18 − 2 · (3 + 4).", "topic": "Kolejność działań", "options": ["112", "16", "28", "4"], "correct": 3, "explanation": "Najpierw nawias: 3 + 4 = 7. Potem mnożenie: 2 · 7 = 14. Na końcu 18 − 14 = 4."}, {"no": 13, "question": "Oblicz: (−6) · 4 + 10.", "topic": "Liczby ujemne", "options": ["−14", "−34", "14", "34"], "correct": 0, "explanation": "(−6) · 4 = −24. Następnie −24 + 10 = −14."}, {"no": 14, "question": "Oblicz: 2³ · 2².", "topic": "Potęgi", "options": ["16", "32", "12", "64"], "correct": 1, "explanation": "Przy mnożeniu potęg o tej samej podstawie dodajemy wykładniki: 2³ · 2² = 2⁵ = 32."}, {"no": 15, "question": "Oblicz: 5⁴ : 5².", "topic": "Potęgi", "options": ["10", "625", "25", "5"], "correct": 2, "explanation": "Przy dzieleniu potęg o tej samej podstawie odejmujemy wykładniki: 5⁴ : 5² = 5² = 25."}, {"no": 16, "question": "Zapis (3²)³ jest równy:", "topic": "Potęgi", "options": ["3⁵", "3⁸", "3⁹", "3⁶"], "correct": 3, "explanation": "Potęgując potęgę, mnożymy wykładniki: 2 · 3 = 6. Zatem (3²)³ = 3⁶."}, {"no": 17, "question": "Który zapis naukowy odpowiada liczbie 4 500 000?", "topic": "Zapis naukowy", "options": ["4,5 · 10⁶", "45 · 10⁶", "4,5 · 10⁵", "0,45 · 10⁶"], "correct": 0, "explanation": "Przesuwamy przecinek o sześć miejsc w lewo: 4 500 000 = 4,5 · 10⁶. Pierwszy czynnik w zapisie naukowym ma wartość od 1 do mniej niż 10."}, {"no": 18, "question": "Oblicz: √81.", "topic": "Pierwiastki", "options": ["41", "9", "−9", "18"], "correct": 1, "explanation": "Symbol √81 oznacza nieujemny pierwiastek kwadratowy. Ponieważ 9² = 81, √81 = 9."}, {"no": 19, "question": "Oblicz: ∛(−27).", "topic": "Pierwiastki", "options": ["−9", "9", "−3", "3"], "correct": 2, "explanation": "(−3)³ = −27, więc pierwiastek sześcienny z −27 wynosi −3."}, {"no": 20, "question": "Wyłącz czynnik przed pierwiastek: √50.", "topic": "Pierwiastki", "options": ["25√2", "2√5", "5√10", "5√2"], "correct": 3, "explanation": "50 = 25 · 2, więc √50 = √25 · √2 = 5√2."}]'::jsonb),
('liczby8-sredni-v1','Liczby i działania · średni','Matematyka','8','','testy/matematyka/liczby-dzialania.html?poziom=sredni','[{"no": 1, "question": "Ile wynosi liczba zapisana jako MCMXLIV?", "topic": "Liczby rzymskie", "options": ["1944", "1964", "1844", "2044"], "correct": 0, "explanation": "M = 1000, CM = 900, XL = 40, IV = 4. Razem 1944."}, {"no": 2, "question": "Jaką cyfrę należy wstawić w miejsce □ w liczbie 4□2, aby liczba była podzielna przez 9?", "topic": "Podzielność", "options": ["9", "3", "0", "6"], "correct": 1, "explanation": "Suma cyfr to 4 + □ + 2 = 6 + □. Jedyna możliwa wielokrotność 9 to 9, więc □ = 3."}, {"no": 3, "question": "Która liczba jest podzielna przez 6?", "topic": "Podzielność", "options": ["2133", "2140", "2136", "2123"], "correct": 2, "explanation": "Podzielność przez 6 wymaga podzielności przez 2 i 3. 2136 jest parzyste, a suma jego cyfr wynosi 12."}, {"no": 4, "question": "Ile cyfr można wstawić w miejsce □ w liczbie 53□, aby liczba była podzielna przez 4?", "topic": "Podzielność", "options": ["1", "3", "4", "2"], "correct": 3, "explanation": "O podzielności przez 4 decydują dwie ostatnie cyfry. Wśród 30–39 przez 4 dzielą się 32 i 36, więc pasują dwie cyfry: 2 oraz 6."}, {"no": 5, "question": "Który rozkład liczby 180 jest poprawny?", "topic": "Rozkład na czynniki", "options": ["2² · 3² · 5", "2 · 3² · 5", "2² · 3 · 5²", "2³ · 3 · 5"], "correct": 0, "explanation": "180 = 18 · 10 = (2 · 3²) · (2 · 5) = 2² · 3² · 5."}, {"no": 6, "question": "Z 36 czerwonych i 48 niebieskich koralików powstają jednakowe zestawy. Wszystkie koraliki mają zostać wykorzystane. Ile zestawów można zrobić maksymalnie?", "topic": "NWD", "options": ["24", "12", "6", "18"], "correct": 1, "explanation": "Maksymalna liczba jednakowych zestawów to NWD(36,48) = 12. Każdy zawiera 3 czerwone i 4 niebieskie koraliki."}, {"no": 7, "question": "Dwa dzwonki dzwonią co 12 i co 18 minut. Zadzwoniły razem o 10:00. O której najwcześniej zadzwonią ponownie razem?", "topic": "NWW", "options": ["10:30", "10:48", "10:36", "10:24"], "correct": 2, "explanation": "NWW(12,18) = 36. Po 36 minutach będzie 10:36."}, {"no": 8, "question": "Która liczba jest niewymierna?", "topic": "Rodzaje liczb", "options": ["√49", "0,125", "−7/3", "√18"], "correct": 3, "explanation": "√18 = 3√2 jest niewymierne. √49 = 7, skończony ułamek dziesiętny i iloraz liczb całkowitych są wymierne."}, {"no": 9, "question": "Wybierz poprawną kolejność od najmniejszej do największej.", "topic": "Porównywanie liczb", "options": ["−0,8 < −3/4 < −0,7", "−3/4 < −0,8 < −0,7", "−0,7 < −3/4 < −0,8", "−0,8 < −0,7 < −3/4"], "correct": 0, "explanation": "−3/4 = −0,75. Z liczb ujemnych mniejsza jest ta o większej wartości bezwzględnej: −0,8 < −0,75 < −0,7."}, {"no": 10, "question": "Oblicz: (2/3 − 1/4) : (5/6).", "topic": "Działania na ułamkach", "options": ["1/3", "1/2", "5/9", "25/72"], "correct": 1, "explanation": "W nawiasie: 8/12 − 3/12 = 5/12. Dzielenie zamieniamy na mnożenie przez odwrotność: (5/12) · (6/5) = 1/2."}, {"no": 11, "question": "Oblicz: −3² + (−3)².", "topic": "Kolejność działań", "options": ["−18", "6", "0", "18"], "correct": 2, "explanation": "−3² = −(3²) = −9, natomiast (−3)² = 9. Suma wynosi 0."}, {"no": 12, "question": "Oblicz: (2⁵ · 2³) : 2⁶.", "topic": "Potęgi", "options": ["2", "8", "16", "4"], "correct": 3, "explanation": "Dodajemy wykładniki w liczniku i odejmujemy wykładnik w mianowniku: 2⁵⁺³⁻⁶ = 2² = 4."}, {"no": 13, "question": "Oblicz: (3²)³ : 3⁴.", "topic": "Potęgi", "options": ["9", "3", "27", "81"], "correct": 0, "explanation": "(3²)³ = 3⁶. Następnie 3⁶ : 3⁴ = 3² = 9."}, {"no": 14, "question": "Zapis naukowy liczby 0,00072 to:", "topic": "Zapis naukowy", "options": ["72 · 10⁻⁴", "7,2 · 10⁻⁴", "7,2 · 10⁴", "7,2 · 10⁻³"], "correct": 1, "explanation": "Przecinek przesuwamy o 4 miejsca w prawo, więc mnożymy przez 10⁻⁴. 7,2 · 0,0001 = 0,00072."}, {"no": 15, "question": "Oblicz (6 · 10⁵) · (3 · 10³) i podaj wynik w zapisie naukowym.", "topic": "Zapis naukowy", "options": ["1,8 · 10⁸", "9 · 10⁸", "1,8 · 10⁹", "18 · 10⁹"], "correct": 2, "explanation": "6 · 3 = 18 i 10⁵ · 10³ = 10⁸. Mamy 18 · 10⁸ = 1,8 · 10⁹."}, {"no": 16, "question": "Uprość: √72 − √8.", "topic": "Pierwiastki", "options": ["8√2", "√64", "2√2", "4√2"], "correct": 3, "explanation": "√72 = 6√2, a √8 = 2√2. Odejmujemy współczynniki: 6√2 − 2√2 = 4√2."}, {"no": 17, "question": "Oblicz: √(9/16).", "topic": "Pierwiastki", "options": ["3/4", "9/4", "3/16", "−3/4"], "correct": 0, "explanation": "√(9/16) = √9/√16 = 3/4. Pierwiastek kwadratowy jest nieujemny."}, {"no": 18, "question": "Usuń niewymierność z mianownika: 6/√3.", "topic": "Pierwiastki", "options": ["2", "2√3", "6√3", "3√2"], "correct": 1, "explanation": "Mnożymy licznik i mianownik przez √3: (6√3)/3 = 2√3."}, {"no": 19, "question": "Oblicz: ∛(−64) + √144.", "topic": "Pierwiastki", "options": ["−16", "−8", "8", "16"], "correct": 2, "explanation": "∛(−64) = −4, a √144 = 12. Suma: −4 + 12 = 8."}, {"no": 20, "question": "Oblicz: 2,4 : 0,6 − (1/2)².", "topic": "Kolejność działań", "options": ["3,5", "0,75", "4,25", "3,75"], "correct": 3, "explanation": "2,4 : 0,6 = 4, a (1/2)² = 1/4 = 0,25. Wynik: 4 − 0,25 = 3,75."}]'::jsonb),
('liczby8-trudny-v1','Liczby i działania · trudny','Matematyka','8','','testy/matematyka/liczby-dzialania.html?poziom=trudny','[{"no": 1, "question": "Rok zapisano jako MDCCXCIX. Jak zapisać po rzymsku rok o 6 lat późniejszy?", "topic": "Liczby rzymskie", "options": ["MDCCCV", "MDCCXCVI", "MDCCCIV", "MDCCCVI"], "correct": 0, "explanation": "MDCCXCIX = 1799. Dodajemy 6: 1805. 1800 = MDCCC, a 5 = V, więc MDCCCV."}, {"no": 2, "question": "Jaką cyfrę □ trzeba wybrać, aby liczba 7□2 była podzielna jednocześnie przez 4 i 9?", "topic": "Podzielność", "options": ["9", "0", "2", "6"], "correct": 0, "explanation": "Podzielność przez 9: 7 + □ + 2 = 9 + □, więc □ = 0 albo 9. Podzielność przez 4: końcówka 02 nie dzieli się przez 4, a 92 dzieli się przez 4. Zatem □ = 9."}, {"no": 3, "question": "Ile liczb całkowitych od 100 do 199 włącznie jest podzielnych przez 6, ale nie przez 9?", "topic": "Podzielność", "options": ["12", "16", "11", "10"], "correct": 2, "explanation": "Wielokrotności 6 w tym przedziale to 102,108,…,198 — jest ich 17. Wspólne wielokrotności 6 i 9 to wielokrotności 18: 108,126,…,198 — jest ich 6. Wynik: 17 − 6 = 11."}, {"no": 4, "question": "Które zdanie jest prawdziwe?", "topic": "Liczby pierwsze", "options": ["Suma dwóch liczb pierwszych zawsze jest pierwsza.", "Każda nieparzysta liczba większa od 1 jest pierwsza.", "Liczba 1 jest najmniejszą liczbą pierwszą.", "Iloczyn dwóch liczb pierwszych jest liczbą złożoną."], "correct": 3, "explanation": "Liczby pierwsze są większe od 1. Ich iloczyn ma dzielnik różny od 1 i od samego iloczynu, więc jest złożony. Pozostałe zdania obalają np. 3 + 5 = 8 oraz liczba 9."}, {"no": 5, "question": "Prostokąt o wymiarach 84 cm i 126 cm trzeba podzielić na jednakowe kwadraty o największym możliwym całkowitym boku. Ile kwadratów powstanie?", "topic": "NWD", "options": ["6", "3", "42", "9"], "correct": 0, "explanation": "Bok kwadratu to NWD(84,126) = 42 cm. Wymiary dają 84/42 = 2 i 126/42 = 3 kwadraty. Łącznie 2 · 3 = 6."}, {"no": 6, "question": "Dwie liczby dodatnie mają NWD równy 6 i NWW równą 180. Jedna z liczb to 30. Jaka jest druga?", "topic": "NWD i NWW", "options": ["18", "36", "60", "24"], "correct": 1, "explanation": "Dla dwóch dodatnich liczb całkowitych a · b = NWD(a,b) · NWW(a,b). Zatem 30 · b = 6 · 180, więc b = 36. Sprawdzenie: NWD(30,36)=6 i NWW(30,36)=180."}, {"no": 7, "question": "Trzy lampki migają co 8, 12 i 18 sekund. Ile razy zamigają jednocześnie przez 5 minut po wspólnym mignięciu na początku? Nie licz chwili początkowej.", "topic": "NWW", "options": ["5", "6", "4", "3"], "correct": 2, "explanation": "NWW(8,12,18) = 72. W 300 sekundach wspólne mignięcia nastąpią po 72,144,216 i 288 sekundach — cztery razy."}, {"no": 8, "question": "Która z poniższych liczb jest wymierna?", "topic": "Rodzaje liczb", "options": ["√12 + √3", "√18 − √8", "√5/2", "√12 · √3"], "correct": 3, "explanation": "√12 · √3 = √36 = 6. Pozostałe liczby to odpowiednio 3√3, √2 oraz √5/2 — są niewymierne."}, {"no": 9, "question": "Wybierz poprawną kolejność od najmniejszej do największej.", "topic": "Porównywanie liczb", "options": ["1,41 < √2 < 10/7", "√2 < 1,41 < 10/7", "1,41 < 10/7 < √2", "10/7 < √2 < 1,41"], "correct": 0, "explanation": "√2 ≈ 1,4142, a 10/7 ≈ 1,4286. Zatem 1,41 < √2 < 10/7."}, {"no": 10, "question": "Oblicz: [3/4 − (1/2 − 1/3)] : (7/6).", "topic": "Działania na ułamkach", "options": ["49/72", "1/2", "7/12", "2/3"], "correct": 1, "explanation": "Najpierw 1/2 − 1/3 = 1/6. Potem 3/4 − 1/6 = 7/12. Na końcu (7/12) · (6/7) = 1/2."}, {"no": 11, "question": "Oblicz: −2⁴ + (−2)⁴ − (−2)³.", "topic": "Kolejność działań", "options": ["24", "40", "8", "−8"], "correct": 2, "explanation": "−2⁴ = −16, (−2)⁴ = 16, (−2)³ = −8. Mamy −16 + 16 − (−8) = 8."}, {"no": 12, "question": "Uprość i oblicz: (2⁴ · 8²) : 4³.", "topic": "Potęgi", "options": ["4", "8", "64", "16"], "correct": 3, "explanation": "Zapisujemy wszystko jako potęgi 2: 8² = 2⁶ i 4³ = 2⁶. Otrzymujemy 2⁴⁺⁶⁻⁶ = 2⁴ = 16."}, {"no": 13, "question": "Dla jakiej liczby całkowitej n zachodzi 3ⁿ · 9² = 3⁷?", "topic": "Potęgi", "options": ["3", "2", "4", "5"], "correct": 0, "explanation": "9² = (3²)² = 3⁴. Zatem 3ⁿ⁺⁴ = 3⁷, czyli n + 4 = 7 i n = 3."}, {"no": 14, "question": "Oblicz (1,2 · 10⁷) : (3 · 10³) i podaj wynik w zapisie naukowym.", "topic": "Zapis naukowy", "options": ["3,6 · 10¹⁰", "4 · 10³", "4 · 10⁴", "0,4 · 10³"], "correct": 1, "explanation": "1,2 : 3 = 0,4 i 10⁷ : 10³ = 10⁴. Zatem 0,4 · 10⁴ = 4 · 10³."}, {"no": 15, "question": "Ziarno ma masę 2,5 · 10⁻⁴ kg. Ile takich ziaren waży łącznie 0,6 kg?", "topic": "Zapis naukowy", "options": ["24 000", "1500", "2400", "240"], "correct": 2, "explanation": "Liczba ziaren to 0,6 : 0,00025 = 2400."}, {"no": 16, "question": "Uprość: 3√8 − 2√18 + √50.", "topic": "Pierwiastki", "options": ["√2", "11√2", "7√2", "5√2"], "correct": 3, "explanation": "3√8 = 6√2, 2√18 = 6√2, √50 = 5√2. Razem 6√2 − 6√2 + 5√2 = 5√2."}, {"no": 17, "question": "Usuń niewymierność z mianownika: 5/(2√5).", "topic": "Pierwiastki", "options": ["√5/2", "2√5", "5√5/2", "√5/10"], "correct": 0, "explanation": "Mnożymy licznik i mianownik przez √5. Dostajemy (5√5)/(2 · 5) = √5/2."}, {"no": 18, "question": "Dla a = −7 oblicz √(a²) + a.", "topic": "Pierwiastki", "options": ["7", "0", "−14", "14"], "correct": 1, "explanation": "√(a²) = |a|. Dla a = −7 jest to 7. Zatem 7 + (−7) = 0."}, {"no": 19, "question": "Oblicz: (√12 · √27)/√9.", "topic": "Pierwiastki", "options": ["3", "9", "6", "18"], "correct": 2, "explanation": "√12 · √27 = √324 = 18, a √9 = 3. Iloraz: 18/3 = 6."}, {"no": 20, "question": "Oblicz: (√50/√2)² − ∛125.", "topic": "Pierwiastki i potęgi", "options": ["0", "10", "30", "20"], "correct": 3, "explanation": "√50/√2 = √25 = 5. Następnie 5² − 5 = 25 − 5 = 20."}]'::jsonb);
